import{j as e,Y as n,a2 as o}from"./index-DERvnYD6.js";const r=[{title:"1. Qué es una adopción",body:[`Adoptar un árbol en ${o} es apadrinar su siembra y su cuidado dentro de un bosque de conservación en Manglaralto, Santa Elena, Ecuador. Es un aporte a un proyecto ambiental, no una compra de terreno ni de madera.`,"La adopción no otorga propiedad sobre el suelo, el árbol ni sus frutos, ni ningún derecho real sobre el predio. El padrino recibe el reconocimiento de su árbol, su seguimiento y la posibilidad de visitarlo."]},{title:"2. Qué incluye",body:["La plántula producida en el vivero del proyecto, la siembra, 3 años de cuidado (riego, control de maleza y protección) y la reposición sin costo si el árbol no prospera durante ese período.","Un certificado digital con código QR, la página propia del árbol con su ubicación, fotos y novedades, y la visita al bosque coordinada previamente con la gestión del proyecto."]},{title:"3. Reserva, pago y confirmación",body:["Al enviar el formulario la adopción queda reservada y, si elegiste un árbol en el mapa, ese árbol queda apartado a tu nombre. El pago se coordina por WhatsApp.","La adopción se confirma cuando se acredita el pago. Si el pago no se concreta en 7 días, la reserva puede liberarse para otra persona."]},{title:"4. Ubicación del árbol",body:["Las ubicaciones del mapa provienen del plano de siembra. Al sembrar, la posición puede ajustarse unos metros por condiciones del terreno. La ubicación definitiva se registra en la página del árbol.","Si adoptas sin elegir un árbol en el mapa, se te asigna uno de la especie elegida al momento de la siembra."]},{title:"5. Conservación permanente",body:["Los árboles del bosque no se talan ni se aprovechan como madera. Solo se realizan podas de mantenimiento o sanidad. La cosecha de los frutales se destina al restaurante de Montañita View Lobby y a la comunidad."]},{title:"6. Nombre público y fotos",body:['El nombre del padrino, o el de la dedicatoria, se muestra en el mapa, en la página del árbol y en el certificado. Si prefieres que no se muestre, indícalo al adoptar y aparecerá como "Padrino anónimo".',"Las fotos del bosque y de los árboles pueden usarse en la comunicación del proyecto."]},{title:"7. Cancelación y reembolso",body:["Puedes cancelar y recibir el reembolso total mientras el árbol no haya sido sembrado. Una vez sembrado, el aporte ya se destinó a su siembra y cuidado y no es reembolsable."]},{title:"8. Padrino activo (aporte mensual opcional)",body:["El aporte mensual es voluntario y se puede suspender en cualquier momento avisando por WhatsApp. Financia novedades más frecuentes, visitas guiadas y fruta de temporada."]},{title:"9. Casos fuera de nuestro control",body:["Eventos naturales extraordinarios (sequías severas, incendios, crecidas del río u otros de fuerza mayor) pueden afectar al bosque. En esos casos el proyecto repondrá los árboles dentro de sus posibilidades e informará a los padrinos."]},{title:"10. Datos personales",body:["Tus datos de contacto se usan solo para gestionar tu adopción y enviarte novedades del bosque, conforme a la Ley Orgánica de Protección de Datos Personales del Ecuador. No se venden ni se comparten con terceros, y puedes pedir su eliminación."]}];function l(){return e.jsxs("div",{className:"mx-auto max-w-3xl px-4 py-16 sm:px-6",children:[e.jsx(n,{children:e.jsx("title",{children:`Términos de la adopción · ${o}`})}),e.jsx("p",{className:"text-xs font-semibold uppercase tracking-[0.25em] text-bosque/70",children:o}),e.jsx("h1",{className:"mt-2 font-bosque text-5xl font-semibold text-bosque",children:"Términos de la adopción"}),e.jsx("div",{className:"mt-10 space-y-8",children:r.map(a=>e.jsxs("section",{children:[e.jsx("h2",{className:"text-lg font-semibold text-bosque-dark",children:a.title}),a.body.map(s=>e.jsx("p",{className:"mt-2 leading-relaxed text-bosque-dark/80",children:s},s.slice(0,30)))]},a.title))})]})}export{l as default};
